<?php

use Boctulus\Simplerest\Core\Libs\Config;
use Boctulus\Simplerest\Core\Libs\Files;
use Boctulus\Simplerest\Core\Libs\i18n\Translate;

// Application bootstrap (generated by `vendor/bin/simplerest init`).

if (!file_exists(__DIR__ . '/vendor/autoload.php')) {
    fwrite(STDERR, "vendor/autoload.php is missing. Run `composer install` first." . PHP_EOL);
    exit(1);
}

require_once __DIR__ . '/vendor/autoload.php';
require_once __DIR__ . '/config/constants.php';

ini_set('log_errors', 1);
ini_set('error_log', LOGS_PATH . 'errors.txt');

/*
    Modules: Boctulus\Simplerest\Modules\{Module}\... => app/Modules/{Module}/src/...
*/
spl_autoload_register(function (string $class): void {
    $prefix = 'Boctulus\\Simplerest\\Modules\\';
    if (strpos($class, $prefix) !== 0) {
        return;
    }

    $parts = explode('\\', substr($class, strlen($prefix)));
    $module = array_shift($parts);
    $file = APP_PATH . 'Modules' . DIRECTORY_SEPARATOR . $module . DIRECTORY_SEPARATOR . 'src'
        . DIRECTORY_SEPARATOR . implode(DIRECTORY_SEPARATOR, $parts) . '.php';

    if (is_file($file)) {
        require_once $file;
    }
});

/* Helpers: framework helpers first, then application helpers */

Files::mkDir(HELPERS_PATH);
$autoload = include CONFIG_PATH . 'autoload.php';

if (!is_dir(CORE_HELPERS_PATH)) {
    fwrite(STDERR, 'SimpleRest framework helpers not found at ' . CORE_HELPERS_PATH
        . '. Check that boctulus/simplerest is installed (composer install).' . PHP_EOL);
    exit(1);
}

foreach ($autoload['include'] as $entry) {
    if (!is_dir($entry)) {
        if (pathinfo($entry, PATHINFO_EXTENSION) !== 'php' || !is_file($entry)) {
            fwrite(STDERR, "config/autoload.php lists a path that does not exist: {$entry}" . PHP_EOL);
            exit(1);
        }
        require_once $entry;
        continue;
    }

    foreach (new \DirectoryIterator($entry) as $fileInfo) {
        if ($fileInfo->isDot() || str_starts_with($fileInfo->getFilename(), '_')) {
            continue;
        }

        $path = $fileInfo->getPathname();
        if (in_array($path, $autoload['exclude'], true)) {
            continue;
        }

        if (pathinfo($path, PATHINFO_EXTENSION) === 'php') {
            require_once $path;
        }
    }
}

$config = array_merge(
    include CONFIG_PATH . 'config.php',
    include CONFIG_PATH . 'databases.php'
);
Config::set('', $config);

/* i18n (boctulus/simplerest-i18n) */

Translate::useGettext($config['translate']['use_gettext']);

if (PHP_SAPI === 'cli') {
    $lang = null;
} else {
    $req  = request();
    $lang = $req->shiftQuery('lang') ?? $req->header('Accept-Language');
}

setLang($lang);

foreach ($config['providers'] as $provider) {
    $p = new $provider();
    $p->register();
    $p->boot();
}

if (isset($config['DateTimeZone'])) {
    date_default_timezone_set($config['DateTimeZone']);
}

if (PHP_SAPI === 'cli' || $config['debug']) {
    ini_set('display_errors', 1);
    ini_set('display_startup_errors', 1);
    error_reporting(E_ALL);
} else {
    ini_set('display_errors', 0);
    error_reporting(0);
}
